import type { Country, Detection, Genus } from "./types";

// Simulated detections for the test maps ("USA test", "Nigeria test"), generated by scripts/build_*_test_dots.py
// and saved in public/geo. They are shaped like real detection rows, so the map draws and explains them like the rest.

interface Payload {
  species: string[];
  hotspots: string[];
  // [lat * 1000, lng * 1000, age in tenths of a day, hotspot, species, confidence %, flags (bit 0 human, bit 1 trap)]
  dots: number[][];
}

export interface TestDotsSource {
  url: string;
  idPrefix: string;
  country: Country;
  genus: Genus;
  /** Never draw more than this many, whatever the file holds. */
  max: number;
}

const cache = new Map<string, Promise<Payload>>();

export async function loadTestDots(src: TestDotsSource, days: number): Promise<Detection[]> {
  let payload = cache.get(src.url);
  if (!payload) {
    payload = fetch(src.url).then((r) => {
      if (!r.ok) throw new Error(`${src.url} returned ${r.status}: run the matching scripts/build_*_test_dots.py`);
      return r.json() as Promise<Payload>;
    });
    cache.set(src.url, payload);
  }
  const { species, hotspots, dots } = await payload;
  const now = Date.now();
  const out: Detection[] = [];
  dots.slice(0, src.max).forEach(([lat, lng, age, hotspot, sp, conf, flags], i) => {
    if (age / 10 > days) return;
    out.push({
      detection_id: `${src.idPrefix}-${i}`,
      time: new Date(now - (age / 10) * 864e5).toISOString(),
      country: src.country,
      district: `the ${hotspots[hotspot]} area`,
      district_id: `${src.idPrefix}-${hotspot}`, // dots of one hotspot share a colour scale (dark in the middle, light at the edge)
      lat: lat / 1000,
      lng: lng / 1000,
      species: species[sp],
      genus: src.genus,
      confidence: conf / 100,
      source: flags & 2 ? "trap" : "phone",
      is_simulated: true,
    });
  });
  return out;
}
